import pandas as pd
import numpy as np

# Test: pd.Timedelta(0, 's') * np.inf
try:
    result = pd.Timedelta(0, 's') * np.inf
    probe("pd.Timedelta(0, 's') * np.inf", result)
except Exception as e:
    probe("pd.Timedelta(0, 's') * np.inf", "__error__: " + type(e).__name__ + ": " + str(e))

# Test: pd.Timedelta(0, 'ms') * np.inf
try:
    result = pd.Timedelta(0, 'ms') * np.inf
    probe("pd.Timedelta(0, 'ms') * np.inf", result)
except Exception as e:
    probe("pd.Timedelta(0, 'ms') * np.inf", "__error__: " + type(e).__name__ + ": " + str(e))

# Test: pd.Timedelta(0, 'us') * (-np.inf)
try:
    result = pd.Timedelta(0, 'us') * (-np.inf)
    probe("pd.Timedelta(0, 'us') * (-np.inf)", result)
except Exception as e:
    probe("pd.Timedelta(0, 'us') * (-np.inf)", "__error__: " + type(e).__name__ + ": " + str(e))

# Test: pd.Timedelta(0, 'ns') * np.float32('inf')
try:
    result = pd.Timedelta(0, 'ns') * np.float32('inf')
    probe("pd.Timedelta(0, 'ns') * np.float32('inf')", result)
except Exception as e:
    probe("pd.Timedelta(0, 'ns') * np.float32('inf')", "__error__: " + type(e).__name__ + ": " + str(e))

# Test: np.inf * pd.Timedelta(0, 's')
try:
    result = np.inf * pd.Timedelta(0, 's')
    probe("np.inf * pd.Timedelta(0, 's')", result)
except Exception as e:
    probe("np.inf * pd.Timedelta(0, 's')", "__error__: " + type(e).__name__ + ": " + str(e))

