    probe("expected::pd.Timedelta(0, 's') * np.inf", expected)
except Exception as e:
    probe("expected::pd.Timedelta(0, 's') * np.inf", "__error__: " + type(e).__name__ + ": " + str(e))

try:
    expected = pd.NaT
    probe("expected::pd.Timedelta(0, 'ms') * np.inf", expected)
except Exception as e:
    probe("expected::pd.Timedelta(0, 'ms') * np.inf", "__error__: " + type(e).__name__ + ": " + str(e))

try:
    expected = pd.NaT
    probe("expected::pd.Timedelta(0, 'us') * (-np.inf)", expected)
except Exception as e:
    probe("expected::pd.Timedelta(0, 'us') * (-np.inf)", "__error__: " + type(e).__name__ + ": " + str(e))

